import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { setTimeout as delay } from 'node:timers/promises';
import { createDashboardHarness } from './dashboard-fixture.mjs';
import { report } from '../../scripts/test-environment.mjs';
import { dashboardPerformanceSummary } from '../../scripts/dashboard-performance.mjs';
import { candidateFingerprint } from '../../scripts/evaluation-manifest.mjs';

function fixtureError(name, code) {
  // Cypress must never receive a database URL or private evidence in a cause.
  return new Error(`No se completó el fixture de revisión (${name}; ${code}).`);
}

export async function createSignalReviewHarness(state) {
  const base = await createDashboardHarness(state);
  const database = base.database;
  const scopes = new Map();
  const profiles = new Map();
  const batchCandidates = new Map();
  let load = null;
  function context(input) {
    const value = scopes.get(input.organizationId);
    assert.ok(value, 'Only this fixture own scopes may be modified.');
    return value;
  }
  async function prepare(input = {}) {
    assert.ok(Object.keys(input).every((key) => ['realSubmit'].includes(key)));
    const c = await base.prepare({
      signals: true,
      realSubmit: input.realSubmit !== false,
    });
    c.studentId = c.studentIds[0];
    c.signalId = c.signals.find(
      (item) => item.state === 'ACTIVE' && item.type === 'REPEATED_ERROR',
    )?.id;
    assert.ok(c.signalId, 'A real evaluated ACTIVE episode is required.');
    scopes.set(c.organizationId, c);
    return c;
  }
  async function snapshot(input) {
    const c = context(input);
    const immutable = (
      await database.query(
        `SELECT
        (SELECT md5(coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id)::text,'[]')) FROM app.attempts a WHERE organization_id=$1) AS attempts,
        (SELECT md5(coalesce(jsonb_agg(to_jsonb(e)-ARRAY['state','reviewed_by','reviewed_at','stopped_at','stop_reason'] ORDER BY e.id)::text,'[]')) FROM app_private.signal_episodes e JOIN app_private.signal_lanes l ON l.id=e.lane_id WHERE l.organization_id=$1) AS episodes,
        (SELECT count(*)::int FROM app_private.signal_reviews r JOIN app_private.signal_lanes l ON l.id=r.lane_id WHERE l.organization_id=$1) AS reviews,
        (SELECT count(*)::int FROM app.audit_events WHERE organization_id=$1 AND action='SIGNAL_REVIEWED') AS audits`,
        [c.organizationId],
      )
    ).rows[0];
    const review =
      (
        await database.query(
          'SELECT reviewed_by,app_private.signal_instant(reviewed_at) AS reviewed_at FROM app_private.signal_reviews WHERE episode_id=$1',
          [c.signalId],
        )
      ).rows[0] ?? null;
    return { ...immutable, review };
  }
  async function review(input) {
    const c = context(input);
    return base.request(`/signals/${c.signalId}/review`, {
      method: 'PUT',
      body: {},
    });
  }
  async function query(input) {
    const c = context(input);
    return base.request(
      `/classes/${c.classroomId}/signals/${c.signalId}${input.historical ? `?asOf=${encodeURIComponent(c.asOf)}` : ''}`,
    );
  }
  async function revoke(input) {
    const c = context(input);
    await base.revoke(c, input.actor ?? 'teacher');
    return null;
  }
  async function enrollment(input) {
    const c = context(input);
    await database.query(
      'UPDATE app.class_memberships SET ended_at=CASE WHEN $3 THEN NULL ELSE clock_timestamp() END WHERE organization_id=$1 AND class_id=$2 AND user_id=$4',
      [c.organizationId, c.classroomId, input.restore === true, c.studentId],
    );
    return null;
  }
  async function archive(input) {
    const c = context(input);
    await database.query(
      "UPDATE app.activities SET state='CLOSED',closed_at=clock_timestamp() WHERE class_id=$1 AND state='PUBLISHED'",
      [c.classroomId],
    );
    await database.query(
      'UPDATE app.classes SET archived_at=clock_timestamp() WHERE id=$1',
      [c.classroomId],
    );
    return null;
  }
  async function batch(input) {
    assert.equal(input.count, 51);
    const items = [];
    for (let index = 0; index < input.count; index++)
      items.push(await prepare({ realSubmit: false }));
    assert.equal(new Set(items.map((item) => item.signalId)).size, 51);
    assert.equal(
      (
        await database.query(
          'SELECT count(*)::int AS count FROM app_private.signal_reviews WHERE episode_id=ANY($1::uuid[])',
          [items.map((item) => item.signalId)],
        )
      ).rows[0].count,
      0,
    );
    batchCandidates.set(items[0].signalId, await candidateFingerprint());
    return items;
  }
  async function loadStart() {
    assert.equal(load, null);
    const rows = [];
    for (let index = 0; index < 3; index++) {
      const c = await prepare({ realSubmit: false });
      assert.equal((await review(c)).status, 200);
      rows.push(c);
    }
    const active = {
      id: randomUUID(),
      stop: false,
      count: 0,
      failures: 0,
      running: 0,
      peakConcurrency: 0,
      deadline: Date.now() + 15 * 60_000,
      timedOut: false,
      workers: [],
    };
    load = active;
    active.workers = rows.map(async (c) => {
      while (!active.stop) {
        if (Date.now() >= active.deadline) {
          active.timedOut = true;
          break;
        }
        active.running++;
        active.peakConcurrency = Math.max(
          active.peakConcurrency,
          active.running,
        );
        try {
          if ((await review(c)).status !== 200) active.failures++;
        } catch {
          active.failures++;
        } finally {
          active.count++;
          active.running--;
        }
        if (!active.stop) await delay(20);
      }
    });
    return { loadId: active.id, workers: 3 };
  }
  async function loadStop() {
    if (!load) return null;
    const active = load;
    active.stop = true;
    await Promise.all(active.workers);
    load = null;
    return {
      loadId: active.id,
      count: active.count,
      failures: active.failures,
      peakConcurrency: active.peakConcurrency,
      timedOut: active.timedOut,
      workload:
        'Three sustained idempotent review PUT clients on separate already reviewed episodes.',
    };
  }
  async function uiPerformance(input) {
    assert.ok([1, 4].includes(input.concurrency));
    assert.ok(Array.isArray(input.samples) && input.samples.length <= 50);
    const samples = input.samples.map((sample) => ({
      ...sample,
      concurrency: input.concurrency,
    }));
    const summary = dashboardPerformanceSummary(samples, input.concurrency);
    const candidate = batchCandidates.get(input.firstSignalId);
    const finalCandidate = await candidateFingerprint();
    const candidateUnchanged =
      typeof candidate === 'string' && candidate === finalCandidate;
    const passed =
      summary.passed &&
      candidateUnchanged &&
      new Set(input.samples.map((sample) => sample.signalId)).size === 50 &&
      typeof input.firstSignalId === 'string' &&
      !input.samples.some(
        (sample) => sample.signalId === input.firstSignalId,
      ) &&
      Number.isFinite(input.firstReviewMs) &&
      input.firstReviewMs < 3000 &&
      (input.concurrency === 1 ||
        (input.background?.count >= 3 &&
          input.background.failures === 0 &&
          !input.background.timedOut &&
          input.background.peakConcurrency === 3));
    const value = {
      ...summary,
      passed,
      firstReviewMs: input.firstReviewMs,
      firstSignalId: input.firstSignalId,
      candidateFingerprint: candidate ?? null,
      finalCandidateFingerprint: finalCandidate,
      candidateUnchanged,
      samples: input.samples,
      background: input.background ?? null,
    };
    profiles.set(input.concurrency, value);
    await report(
      'signal-review-ui-performance',
      {
        status: [...profiles.values()].some((entry) => !entry.passed)
          ? 'failed'
          : profiles.size === 2
            ? 'passed'
            : 'incomplete',
        targetMs: 3000,
        percentile: 'nearest-rank',
        profiles: [...profiles.values()],
        recordedAt: new Date().toISOString(),
        environment:
          'LAB TEST Chrome production. Confirmation click to REVIEWED rendered (two animation frames), first sample of each profile separate with services already running (not a cold start), 50 new episodes per profile. Concurrency four is one browser plus three idempotent PUT clients, not four browsers. Fixtures retain canonical deterministic persistence and no remote calls.',
      },
      'imp-06',
    );
    return { passed, p95Ms: value.p95Ms, samples: input.samples.length };
  }
  return {
    ...base,
    prepare,
    snapshot,
    review,
    query,
    revoke,
    enrollment,
    archive,
    batch,
    loadStart,
    loadStop,
    performance: uiPerformance,
    close: async () => {
      await loadStop();
      await base.close();
    },
  };
}

export function signalReviewTasks(state) {
  let ready;
  return Object.fromEntries(
    [
      'prepare',
      'snapshot',
      'review',
      'query',
      'revoke',
      'enrollment',
      'archive',
      'batch',
      'loadStart',
      'loadStop',
      'performance',
    ].map((name) => [
      `signal-review:${name}`,
      async (input) => {
        try {
          ready ??= createSignalReviewHarness(state);
          return await (await ready)[name](input ?? {});
        } catch (error) {
          const code =
            typeof error?.code === 'string' &&
            /^[A-Z0-9_]{3,60}$/.test(error.code)
              ? error.code
              : 'FIXTURE_FAILURE';
          throw fixtureError(name, code);
        }
      },
    ]),
  );
}
